threads.body:
Responses-API blocks are missed. langchain-openai passes `{"type": "input_image", "image_url": ...}` (and `input_text`) through verbatim, so with `use_responses_api=True` the image is dropped - and since `to_input_messages` skips messages with no parts, an image-only message disappears from `gen_ai.input.messages` entirely rather than losing just the image.

Same for standard blocks that carry `file_id` instead of `base64`/`url`.

All four fail on the branch:

```python
@pytest.mark.parametrize(
    "block,expected",
    [
        ({"type": "input_image", "image_url": f"data:image/png;base64,{B64}"}, Blob),
        ({"type": "input_image", "image_url": "https://example.com/a.png"}, Uri),
    ],
)
def test_responses_api_input_image_blocks_are_captured(block, expected):
    messages = to_input_messages([HumanMessage(content=[block])])
    assert messages, "message dropped entirely - no parts extracted"
    assert any(isinstance(p, expected) for p in messages[0].parts)


def test_message_survives_unconvertible_image_block():
    # provider-hosted image, no bytes and no url to record
    messages = to_input_messages(
        [HumanMessage(content=[{"type": "image", "file_id": "file-123"}])]
    )
    assert messages, "message dropped entirely"


def test_text_kept_when_image_block_is_unconvertible():
    messages = to_input_messages(
        [
            HumanMessage(
                content=[
                    {"type": "input_text", "text": "what is in this image?"},
                    {"type": "input_image", "image_url": "https://e/a.png"},
                ]
            )
        ]
    )
    assert messages, "message dropped entirely"
    assert any(isinstance(p, Text) for p in messages[0].parts)
```

Please handle `input_image`/`input_text`, stop dropping the whole message when no part can be built, and add the tests.
